test("due by override scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "proof-threshold", "3.00");
  await ui.setSetting(pg_uma, "grace-days", "0");
  await ui.setSetting(pg_uma, "entry-date", "2026-03-01");
  expect(await ui.addHoliday(pg_uma, "2026-04-03")).toBe(true);
  await ui.setSetting(pg_uma, "pot", "7.77");
  expect(await ui.setSettingDated(pg_uma, "rounding", "half-up", "2026-03-01", "half-up")).toBe(true);
  await ui.setSetting(pg_uma, "review-sla", "1");
  await ui.setSetting(pg_uma, "escalate-after", "7");
  await ui.setSetting(pg_uma, "pending-sla", "4");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B", "tags": "c"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B", "contact": " Ada@x "}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "tags": "a"}));
  const pl_cam_1 = ui.must(await ui.addPlan(pg_uma, p_cam, {"amount": "0.40", "start": "2026-02-20", "end": "2026-04-30", "every": "10"}));
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "10.25", "date": "2026-03-05", "ref": " r-1 "}));
  expect(await ui.editClaim(pg_uma, c_cam_0, {"amount": "0.04"})).toBe(true);
  await ui.setToday(pg_uma, "2026-04-29");
  expect(await ui.editPerson(pg_uma, p_cam, {"grade": "B"})).toBe(true);
  expect(await ui.addComment(pg_uma, c_cam_0, "see note")).toBe(true);
  expect(await ui.claimAction(pg_uma, c_cam_0, "open")).toBe(true);
  const c_cam_1 = ui.must(await ui.split(pg_uma, p_cam, c_cam_0, "0.01"));
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.04");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("2.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("1.00");
